   )
/

-- TABLE: BITACORA_AUDITORIA
CREATE TABLE "BITACORA_AUDITORIA" 
   (	"ID_BITACORA_AUDITORIA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_USUARIO" NUMBER, 
	"ID_ROL" NUMBER, 
	"ROL_CODIGO" VARCHAR2(10 CHAR), 
	"ACCION" VARCHAR2(60 CHAR) NOT NULL ENABLE, 
	"ENTIDAD" VARCHAR2(60 CHAR) NOT NULL ENABLE, 
	"ID_ENTIDAD" NUMBER, 
	"VALORES_ANTERIORES" CLOB, 
	"VALORES_NUEVOS" CLOB, 
	"MOTIVO" VARCHAR2(1000 CHAR), 
	"IP" VARCHAR2(45 CHAR), 
	"FECHA" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_1" CHECK (VALORES_ANTERIORES IS JSON) ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_2" CHECK (VALORES_NUEVOS IS JSON) ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_3" CHECK (ROL_CODIGO IN ('ADMIN','RH','EMPLEADO')) ENABLE, 
	 CONSTRAINT "CK_BITACORA_AUDITORIA_4" CHECK (ACTIVO = 1 AND MODIFICADO_POR IS NULL AND FECHA_MODIFICACION IS NULL) ENABLE, 
	 CONSTRAINT "PK_BITACORA_AUDITORIA" PRIMARY KEY ("ID_BITACORA_AUDITORIA")
  USING INDEX  ENABLE
   )
/

-- TABLE: CARGAS_MASIVAS
CREATE TABLE "CARGAS_MASIVAS" 
   (	"ID_CARGA_MASIVA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_USUARIO" NUMBER NOT NULL ENABLE, 
	"NOMBRE_ARCHIVO" VARCHAR2(200 CHAR) NOT NULL ENABLE, 
	"SHA256" RAW(32) NOT NULL ENABLE, 
	"MODALIDAD" VARCHAR2(15 CHAR) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'VALIDANDO' NOT NULL ENABLE, 
	"TOTAL_FILAS" NUMBER(8,0) DEFAULT 0 NOT NULL ENABLE, 
	"FILAS_VALIDAS" NUMBER(8,0) DEFAULT 0 NOT NULL ENABLE, 
	"FILAS_IMPORTADAS" NUMBER(8,0) DEFAULT 0 NOT NULL ENABLE, 
	"CONFIRMADA_EN" DATE, 
	"RUTA_REPORTE" VARCHAR2(500 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_CARGAS_MASIVAS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CARGAS_MASIVAS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_CARGAS_MASIVAS_1" CHECK (MODALIDAD IN ('TODO_O_NADA','SOLO_VALIDAS')) ENABLE, 
	 CONSTRAINT "CK_CARGAS_MASIVAS_2" CHECK (ESTADO IN ('VALIDANDO','VALIDADA','IMPORTADA','FALLIDA')) ENABLE, 
	 CONSTRAINT "CK_CARGAS_MASIVAS_3" CHECK (TOTAL_FILAS >= 0 AND FILAS_VALIDAS BETWEEN 0 AND TOTAL_FILAS AND FILAS_IMPORTADAS BETWEEN 0 AND FILAS_VALIDAS) ENABLE, 
	 CONSTRAINT "PK_CARGAS_MASIVAS" PRIMARY KEY ("ID_CARGA_MASIVA")
  USING INDEX  ENABLE
   )
/

-- TABLE: CONCEPTOS_NOMINA
CREATE TABLE "CONCEPTOS_NOMINA" 
   (	"ID_CONCEPTO_NOMINA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(120 CHAR) NOT NULL ENABLE, 
	"NATURALEZA" VARCHAR2(10 CHAR) NOT NULL ENABLE, 
	"AFECTA_IGSS" NUMBER(1,0) NOT NULL ENABLE, 
	"AFECTA_ISR" NUMBER(1,0) NOT NULL ENABLE, 
	"AFECTA_PRESTACIONES" NUMBER(1,0) NOT NULL ENABLE, 
	"VIGENTE_DESDE" DATE NOT NULL ENABLE, 
	"VIGENTE_HASTA" DATE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_1" CHECK (NATURALEZA IN ('INGRESO','DESCUENTO','PATRONAL')) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_2" CHECK (AFECTA_IGSS IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_3" CHECK (AFECTA_ISR IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_4" CHECK (AFECTA_PRESTACIONES IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CONCEPTOS_NOMINA_5" CHECK (VIGENTE_HASTA IS NULL OR VIGENTE_HASTA >= VIGENTE_DESDE) ENABLE, 
	 CONSTRAINT "PK_CONCEPTOS_NOMINA" PRIMARY KEY ("ID_CONCEPTO_NOMINA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CONCEPTOS_NOMINA_1" UNIQUE ("CODIGO", "VIGENTE_DESDE")
  USING INDEX  ENABLE
   )
/

-- TABLE: CONFIGURACION_EMPRESA
CREATE TABLE "CONFIGURACION_EMPRESA" 
   (	"ID_CONFIGURACION_EMPRESA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"RAZON_SOCIAL" VARCHAR2(200 CHAR) NOT NULL ENABLE, 
	"NIT" VARCHAR2(20 CHAR) NOT NULL ENABLE, 
	"DIRECCION" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"REPRESENTANTE" VARCHAR2(200 CHAR), 
	"CORREO" VARCHAR2(254 CHAR), 
	"TELEFONO" VARCHAR2(8 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"FORMATO_IGSS" CLOB, 
	 CONSTRAINT "CK_CONFIGURACION_EMPRESA_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_CONFIGURACION_EMPRESA_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_CONFIGURACION_EMPRESA_1" CHECK (REGEXP_LIKE(TELEFONO, '^[0-9]{8}$')) ENABLE, 
	 CONSTRAINT "PK_CONFIGURACION_EMPRESA" PRIMARY KEY ("ID_CONFIGURACION_EMPRESA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CONFIGURACION_EMPRESA_1" UNIQUE ("NIT")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_EMPRESA_IGSS_JSON" CHECK (FORMATO_IGSS IS JSON) ENABLE
   )
/

-- TABLE: CONFIG_CODIGOS
CREATE TABLE "CONFIG_CODIGOS" 
   (	"ID_CONFIG_CODIGO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ENTIDAD" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"PREFIJO" VARCHAR2(10 CHAR), 
	"LONGITUD_MAXIMA" NUMBER(2,0) NOT NULL ENABLE, 
	"PATRON" VARCHAR2(30 CHAR) NOT NULL ENABLE, 
	 CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CHECK (LONGITUD_MAXIMA BETWEEN 1 AND 30) ENABLE, 
	 CHECK (PATRON IN ('GENERICO','EMPLEADO','TRANSACCIONAL')) ENABLE, 
	 PRIMARY KEY ("ID_CONFIG_CODIGO")
  USING INDEX  ENABLE, 
	 UNIQUE ("ENTIDAD")
  USING INDEX  ENABLE
   )
/

