	"MINUTO_ENTRADA" NUMBER(4,0) NOT NULL ENABLE, 
	"MINUTO_SALIDA" NUMBER(4,0) NOT NULL ENABLE, 
	"CRUZA_MEDIANOCHE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"MINUTOS_DESCANSO" NUMBER(4,0) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_HB_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_HB_HORAS" CHECK (MINUTO_ENTRADA BETWEEN 0 AND 1439 AND MINUTO_SALIDA BETWEEN 0 AND 1439 AND CRUZA_MEDIANOCHE IN (0,1) AND MINUTOS_DESCANSO BETWEEN 0 AND 1439 AND MINUTO_SALIDA+1440*CRUZA_MEDIANOCHE-MINUTO_ENTRADA > MINUTOS_DESCANSO AND MINUTO_SALIDA+1440*CRUZA_MEDIANOCHE-MINUTO_ENTRADA <= 1440) ENABLE, 
	 CONSTRAINT "CK_HB_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "PK_HORARIO_BLOQUES" PRIMARY KEY ("ID_HORARIO_BLOQUE")
  USING INDEX  ENABLE
   )
/

-- TABLE: HORARIO_DIAS
CREATE TABLE "HORARIO_DIAS" 
   (	"ID_HORARIO_DIA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_HORARIO" NUMBER NOT NULL ENABLE, 
	"DIA_SEMANA" NUMBER(1,0) NOT NULL ENABLE, 
	"LABORABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"MINUTO_ENTRADA" NUMBER(4,0), 
	"MINUTO_SALIDA" NUMBER(4,0), 
	"CRUZA_MEDIANOCHE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"MINUTOS_DESCANSO" NUMBER(4,0) DEFAULT 0 NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_1" CHECK (DIA_SEMANA BETWEEN 1 AND 7) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_2" CHECK (LABORABLE IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_3" CHECK (CRUZA_MEDIANOCHE IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_4" CHECK (MINUTO_ENTRADA BETWEEN 0 AND 1439) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_5" CHECK (MINUTO_SALIDA BETWEEN 0 AND 1439) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_6" CHECK (MINUTOS_DESCANSO BETWEEN 0 AND 1439) ENABLE, 
	 CONSTRAINT "CK_HORARIO_DIAS_7" CHECK ((LABORABLE = 0 AND MINUTO_ENTRADA IS NULL AND MINUTO_SALIDA IS NULL AND CRUZA_MEDIANOCHE = 0 AND MINUTOS_DESCANSO = 0) OR (LABORABLE = 1 AND MINUTO_ENTRADA IS NOT NULL AND MINUTO_SALIDA IS NOT NULL AND MINUTO_SALIDA + CRUZA_MEDIANOCHE * 1440 - MINUTO_ENTRADA > MINUTOS_DESCANSO AND MINUTO_SALIDA + CRUZA_MEDIANOCHE * 1440 - MINUTO_ENTRADA <= 1440)) ENABLE, 
	 CONSTRAINT "PK_HORARIO_DIAS" PRIMARY KEY ("ID_HORARIO_DIA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_HORARIO_DIAS_1" UNIQUE ("ID_HORARIO", "DIA_SEMANA")
  USING INDEX  ENABLE
   )
/

