	 CONSTRAINT "CK_SOLICITUDES_2" CHECK (DATOS_SOLICITADOS IS JSON) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_3" CHECK (ESTADO <> 'RECHAZADA' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_4" CHECK (ESTADO = 'EN_PROCESO' OR (RESUELTO_POR IS NOT NULL AND RESUELTO_EN IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_5" CHECK (ESTADO <> 'ENTREGADA' OR ENTREGADA_EN IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_SOLICITUDES" PRIMARY KEY ("ID_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_SOLICITUDES_1" UNIQUE ("ID_SOLICITUD", "ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_SOLICITUDES_CODIGO" UNIQUE ("CODIGO")
