	 CONSTRAINT "CK_ANUNCIO_DESTINATARIOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_ANUNCIO_DESTINATARIOS_1" CHECK ((CASE WHEN ID_DEPARTAMENTO IS NULL THEN 0 ELSE 1 END + CASE WHEN ID_PUESTO IS NULL THEN 0 ELSE 1 END + CASE WHEN ID_JEFATURA IS NULL THEN 0 ELSE 1 END) = 1) ENABLE, 
