	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE, 
	"ESTADO" VARCHAR2(15 CHAR) DEFAULT 'VIGENTE' NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ID_SOLICITUD" NUMBER, 
	"CODIGO" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	"PERIODICIDAD" VARCHAR2(7 CHAR) DEFAULT 'MENSUAL' NOT NULL ENABLE, 
	"FECHA_FIN_ANTERIOR" DATE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_1" CHECK (MODALIDAD IN ('FIJO','CUOTAS','UNICO')) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_2" CHECK (MONTO_QUINCENA > 0) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_3" CHECK (MONTO_TOTAL > 0) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_4" CHECK (SALDO >= 0 AND SALDO <= MONTO_TOTAL) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_5" CHECK (NUMERO_CUOTAS > 0) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_6" CHECK (FECHA_FIN IS NULL OR FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_7" CHECK (ESTADO IN ('VIGENTE','LIQUIDADO','CANCELADO')) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_8" CHECK ((MODALIDAD = 'FIJO' AND MONTO_TOTAL IS NULL AND SALDO IS NULL AND NUMERO_CUOTAS IS NULL) OR (MODALIDAD IN ('CUOTAS','UNICO') AND MONTO_TOTAL IS NOT NULL AND SALDO IS NOT NULL AND NUMERO_CUOTAS IS NOT NULL AND MONTO_QUINCENA <= MONTO_TOTAL)) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_9" CHECK (MODALIDAD <> 'UNICO' OR NUMERO_CUOTAS = 1) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_EMPLEADO_10" CHECK (ESTADO <> 'LIQUIDADO' OR SALDO = 0) ENABLE, 
	 CONSTRAINT "PK_DESCUENTOS_EMPLEADO" PRIMARY KEY ("ID_DESCUENTO_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_DESCUENTOS_EMPLEADO_1" UNIQUE ("ID_DESCUENTO_EMPLEADO", "ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_DESCUENTO_TRAMITE" UNIQUE ("ID_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_DESCUENTOS_EMPLEADO_CODIGO" UNIQUE ("CODIGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_DESCUENTO_MENSUAL" CHECK (PERIODICIDAD='MENSUAL') ENABLE
   )
/

-- TABLE: EVENTO_DESTINATARIOS
CREATE TABLE "EVENTO_DESTINATARIOS" 
   (	"ID_EVENTO_DESTINATARIO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EVENTO" NUMBER NOT NULL ENABLE, 
	"ID_DEPARTAMENTO" NUMBER, 
	"ID_PUESTO" NUMBER, 
	"ID_JEFATURA" NUMBER, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_EVENTO_DESTINATARIOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_EVENTO_DESTINATARIOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_EVENTO_DESTINATARIOS_1" CHECK ((CASE WHEN ID_DEPARTAMENTO IS NULL THEN 0 ELSE 1 END + CASE WHEN ID_PUESTO IS NULL THEN 0 ELSE 1 END + CASE WHEN ID_JEFATURA IS NULL THEN 0 ELSE 1 END) = 1) ENABLE, 
	 CONSTRAINT "PK_EVENTO_DESTINATARIOS" PRIMARY KEY ("ID_EVENTO_DESTINATARIO")
  USING INDEX  ENABLE
   )
/

-- TABLE: NOMINA_EMPLEADO
CREATE TABLE "NOMINA_EMPLEADO" 
   (	"ID_NOMINA_EMPLEADO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PERIODO_NOMINA" NUMBER NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_HISTORIAL_SALARIAL" NUMBER NOT NULL ENABLE, 
	"VERSION_CALCULO" NUMBER(5,0) NOT NULL ENABLE, 
	"DIAS_PAGADOS" NUMBER(5,2) NOT NULL ENABLE, 
	"SALARIO_BASE" NUMBER(12,2) NOT NULL ENABLE, 
	"TOTAL_INGRESOS" NUMBER(12,2) NOT NULL ENABLE, 
	"TOTAL_DESCUENTOS" NUMBER(12,2) NOT NULL ENABLE, 
	"NETO" NUMBER(12,2) NOT NULL ENABLE, 
	"COSTO_PATRONAL" NUMBER(12,2) NOT NULL ENABLE, 
	"DATOS_EMPLEADO" CLOB NOT NULL ENABLE, 
	"FECHA_PAGO" DATE, 
	"REFERENCIA_PAGO" VARCHAR2(100 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_1" CHECK (VERSION_CALCULO > 0) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_2" CHECK (DIAS_PAGADOS BETWEEN 0 AND 30) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_3" CHECK (SALARIO_BASE > 0) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_4" CHECK (TOTAL_INGRESOS >= 0 AND TOTAL_DESCUENTOS >= 0 AND COSTO_PATRONAL >= 0) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_5" CHECK (NETO >= 0 AND NETO = TOTAL_INGRESOS - TOTAL_DESCUENTOS) ENABLE, 
	 CONSTRAINT "CK_NOMINA_EMPLEADO_6" CHECK (DATOS_EMPLEADO IS JSON) ENABLE, 
	 CONSTRAINT "PK_NOMINA_EMPLEADO" PRIMARY KEY ("ID_NOMINA_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_NOMINA_EMPLEADO_1" UNIQUE ("ID_PERIODO_NOMINA", "ID_EMPLEADO", "VERSION_CALCULO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_NOMINA_EMPLEADO_2" UNIQUE ("ID_NOMINA_EMPLEADO", "ID_EMPLEADO", "ID_PERIODO_NOMINA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_NOMINA_EMPLEADO_PROPIETARIO" UNIQUE ("ID_NOMINA_EMPLEADO", "ID_EMPLEADO")
  USING INDEX  ENABLE
   )
/

-- TABLE: SOLICITUD_HISTORIAL
CREATE TABLE "SOLICITUD_HISTORIAL" 
   (	"ID_SOLICITUD_HISTORIAL" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_SOLICITUD" NUMBER NOT NULL ENABLE, 
	"ESTADO_ANTERIOR" VARCHAR2(12 CHAR), 
	"ESTADO_NUEVO" VARCHAR2(12 CHAR) NOT NULL ENABLE, 
	"ID_USUARIO" NUMBER NOT NULL ENABLE, 
	"FECHA" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(1000 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"TIPO_MOVIMIENTO" VARCHAR2(12 CHAR) DEFAULT 'ESTADO' NOT NULL ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_4" CHECK (ESTADO_NUEVO <> 'RECHAZADA' OR MOTIVO IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_SOLICITUD_HISTORIAL" PRIMARY KEY ("ID_SOLICITUD_HISTORIAL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_HISTORIAL_TIPO" CHECK (TIPO_MOVIMIENTO IN ('ESTADO','REEMISION')) ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_1" CHECK (ESTADO_ANTERIOR IN ('EN_PROCESO','APROBADA','RECHAZADA','ENTREGADA','CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_2" CHECK (ESTADO_NUEVO IN ('EN_PROCESO','APROBADA','RECHAZADA','ENTREGADA','CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_SOLICITUD_HISTORIAL_3" CHECK (
 (TIPO_MOVIMIENTO='ESTADO' AND (
  (ESTADO_ANTERIOR IS NULL AND ESTADO_NUEVO='EN_PROCESO') OR
  (ESTADO_ANTERIOR='EN_PROCESO' AND ESTADO_NUEVO IN ('APROBADA','RECHAZADA')) OR
  (ESTADO_ANTERIOR='APROBADA' AND ESTADO_NUEVO IN ('ENTREGADA','CANCELADA'))
 )) OR
 (TIPO_MOVIMIENTO='REEMISION' AND ESTADO_ANTERIOR IN ('APROBADA','ENTREGADA') AND ESTADO_NUEVO='APROBADA' AND MOTIVO IS NOT NULL)
) ENABLE
   )
/

-- TABLE: VACACIONES_SOLICITUDES
CREATE TABLE "VACACIONES_SOLICITUDES" 
   (	"ID_VACACIONES_SOLICITUD" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE NOT NULL ENABLE, 
	"DIAS_SOLICITADOS" NUMBER(7,2) NOT NULL ENABLE, 
	"SALDO_AL_SOLICITAR" NUMBER(7,2) NOT NULL ENABLE, 
	"SALDO_AL_RESOLVER" NUMBER(7,2), 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'EN_PROCESO' NOT NULL ENABLE, 
	"RESUELTO_POR" NUMBER, 
	"RESUELTO_EN" DATE, 
	"MOTIVO_RECHAZO" VARCHAR2(500 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ID_SOLICITUD" NUMBER NOT NULL ENABLE, 
	"CANCELADO_POR" NUMBER, 
	"CANCELADO_EN" DATE, 
	"MOTIVO_CANCELACION" VARCHAR2(500 CHAR), 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_1" CHECK (FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_2" CHECK (DIAS_SOLICITADOS > 0) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_3" CHECK (SALDO_AL_SOLICITAR >= 0) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_4" CHECK (SALDO_AL_RESOLVER >= 0) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_5" CHECK (ESTADO IN ('EN_PROCESO','APROBADA','RECHAZADA','CANCELADA','TOMADA')) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_6" CHECK (ESTADO NOT IN ('APROBADA','TOMADA') OR (SALDO_AL_RESOLVER IS NOT NULL AND SALDO_AL_RESOLVER >= DIAS_SOLICITADOS AND RESUELTO_POR IS NOT NULL AND RESUELTO_EN IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_SOLICITUDES_7" CHECK (ESTADO <> 'RECHAZADA' OR (MOTIVO_RECHAZO IS NOT NULL AND RESUELTO_POR IS NOT NULL AND RESUELTO_EN IS NOT NULL)) ENABLE, 
	 CONSTRAINT "PK_VACACIONES_SOLICITUDES" PRIMARY KEY ("ID_VACACIONES_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_VACACIONES_SOLICITUDES_1" UNIQUE ("ID_VACACIONES_SOLICITUD", "ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_VACACIONES_TRAMITE" UNIQUE ("ID_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_VACACIONES_CANCELADO" CHECK (CANCELADO_EN IS NULL OR
    (CANCELADO_POR IS NOT NULL AND MOTIVO_CANCELACION IS NOT NULL AND ESTADO='CANCELADA')) ENABLE
   )
/

