-- TABLE: PARQUEO_SUSCRIPCIONES
CREATE TABLE "PARQUEO_SUSCRIPCIONES" 
   (	"ID_PARQUEO_SUSCRIPCION" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_SOLICITUD" NUMBER, 
	"ID_DESCUENTO_ORIGEN" NUMBER, 
	"VEHICULO" VARCHAR2(5 CHAR), 
	"PLACA" VARCHAR2(12 CHAR), 
	"MES_INICIO" DATE NOT NULL ENABLE, 
	"MES_FIN" DATE, 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'ACTIVA' NOT NULL ENABLE, 
	"BAJA_SOLICITADA" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(500 CHAR), 
	"MONTO_ANTERIOR" NUMBER(12,2), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSCRIPCIONES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSCRIPCIONES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION>=FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSC_1" CHECK (VEHICULO IN ('CARRO','MOTO')) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSC_2" CHECK (ESTADO IN ('ACTIVA','BAJA','SUSPENDIDA') AND BAJA_SOLICITADA IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSC_3" CHECK (MES_INICIO=TRUNC(MES_INICIO,'MM') AND (MES_FIN IS NULL OR (MES_FIN>=MES_INICIO AND MES_FIN=TRUNC(MES_FIN,'MM')))) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_SUSC_4" CHECK ((ESTADO='ACTIVA' AND MES_FIN IS NULL) OR (ESTADO<>'ACTIVA' AND MES_FIN IS NOT NULL)) ENABLE, 
	 CONSTRAINT "PK_PARQUEO_SUSCRIPCIONES" PRIMARY KEY ("ID_PARQUEO_SUSCRIPCION")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PARQUEO_SUSC_ORIG" UNIQUE ("ID_DESCUENTO_ORIGEN")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PARQUEO_SUSC_SOL" UNIQUE ("ID_SOLICITUD")
  USING INDEX  ENABLE
   )
/

-- TABLE: PRESTACIONES
CREATE TABLE "PRESTACIONES" 
   (	"ID_PRESTACION" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_PERIODO_NOMINA" NUMBER, 
	"TIPO" VARCHAR2(15 CHAR) NOT NULL ENABLE, 
	"FECHA_INICIO_BASE" DATE NOT NULL ENABLE, 
	"FECHA_FIN_BASE" DATE NOT NULL ENABLE, 
	"FECHA_CALCULO" DATE NOT NULL ENABLE, 
	"SALARIO_PROMEDIO" NUMBER(12,2) NOT NULL ENABLE, 
	"TIEMPO_ANIOS" NUMBER(10,6) NOT NULL ENABLE, 
	"MONTO_TOTAL" NUMBER(12,2) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'CALCULADA' NOT NULL ENABLE, 
	"FECHA_PAGO" DATE, 
	"REFERENCIA_PAGO" VARCHAR2(100 CHAR), 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"HASH_FUENTES" VARCHAR2(64 CHAR), 
	"SNAPSHOT" CLOB, 
	"APROBADO_POR" NUMBER, 
	"APROBADO_EN" DATE, 
	"ID_NOMINA_EMPLEADO" NUMBER, 
	 CONSTRAINT "CK_PRESTACIONES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_1" CHECK (TIPO IN ('AGUINALDO','BONO_14','INDEMNIZACION')) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_2" CHECK (FECHA_FIN_BASE >= FECHA_INICIO_BASE) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_3" CHECK (SALARIO_PROMEDIO >= 0 AND TIEMPO_ANIOS >= 0 AND MONTO_TOTAL >= 0) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_4" CHECK (ESTADO IN ('CALCULADA','APROBADA','PAGADA','ANULADA')) ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_5" CHECK (ESTADO <> 'PAGADA' OR (FECHA_PAGO IS NOT NULL AND REFERENCIA_PAGO IS NOT NULL)) ENABLE, 
	 CONSTRAINT "PK_PRESTACIONES" PRIMARY KEY ("ID_PRESTACION")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_PRESTACIONES_SNAP" CHECK (SNAPSHOT IS JSON) ENABLE
   )
/

