-- TABLE: VACACIONES_MOVIMIENTOS
CREATE TABLE "VACACIONES_MOVIMIENTOS" 
   (	"ID_VACACIONES_MOVIMIENTO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_VACACIONES_SOLICITUD" NUMBER, 
	"TIPO" VARCHAR2(15 CHAR) NOT NULL ENABLE, 
	"FECHA" DATE NOT NULL ENABLE, 
	"DIAS" NUMBER(7,2) NOT NULL ENABLE, 
	"CLAVE_ORIGEN" VARCHAR2(100 CHAR) NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_4" CHECK (TIPO NOT IN ('DISFRUTE','REVERSO') OR ID_VACACIONES_SOLICITUD IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_VACACIONES_MOVIMIENTOS" PRIMARY KEY ("ID_VACACIONES_MOVIMIENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_VACACIONES_MOVIMIENTOS_1" UNIQUE ("ID_EMPLEADO", "CLAVE_ORIGEN")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_1" CHECK (TIPO IN ('ACUMULACION','DISFRUTE','REVERSO','AJUSTE','SALDO_INICIAL')) ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_2" CHECK (DIAS <> 0 OR TIPO='SALDO_INICIAL') ENABLE, 
	 CONSTRAINT "CK_VACACIONES_MOVIMIENTOS_3" CHECK ((TIPO IN ('ACUMULACION','REVERSO') AND DIAS>0) OR (TIPO='DISFRUTE' AND DIAS<0) OR TIPO='AJUSTE' OR (TIPO='SALDO_INICIAL' AND DIAS>=0)) ENABLE
   )
/

-- TABLE: DESCUENTOS_APLICACIONES
CREATE TABLE "DESCUENTOS_APLICACIONES" 
   (	"ID_DESCUENTO_APLICACION" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_NOMINA_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_PERIODO_NOMINA" NUMBER NOT NULL ENABLE, 
	"ID_DESCUENTO_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_DESCUENTO_CUOTA" NUMBER, 
	"MONTO" NUMBER(12,2) NOT NULL ENABLE, 
	"SALDO_ANTERIOR" NUMBER(12,2), 
	"SALDO_NUEVO" NUMBER(12,2), 
	"ESTADO" VARCHAR2(10 CHAR) DEFAULT 'APLICADA' NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_APLICACIONES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_APLICACIONES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_APLICACIONES_1" CHECK (MONTO > 0) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_APLICACIONES_2" CHECK (ESTADO IN ('APLICADA','REVERTIDA')) ENABLE, 
	 CONSTRAINT "CK_DESCUENTOS_APLICACIONES_3" CHECK ((SALDO_ANTERIOR IS NULL AND SALDO_NUEVO IS NULL) OR (SALDO_ANTERIOR IS NOT NULL AND SALDO_NUEVO IS NOT NULL AND SALDO_NUEVO >= 0 AND SALDO_ANTERIOR - MONTO = SALDO_NUEVO)) ENABLE, 
	 CONSTRAINT "PK_DESCUENTOS_APLICACIONES" PRIMARY KEY ("ID_DESCUENTO_APLICACION")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_DESCUENTOS_APLICACIONES_1" UNIQUE ("ID_NOMINA_EMPLEADO", "ID_DESCUENTO_EMPLEADO", "ID_DESCUENTO_CUOTA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_DESCUENTOS_APLICACIONES_2" UNIQUE ("ID_DESCUENTO_APLICACION", "ID_EMPLEADO", "ID_PERIODO_NOMINA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_APLICACION_CALCULO" UNIQUE ("ID_DESCUENTO_APLICACION", "ID_NOMINA_EMPLEADO", "ID_EMPLEADO", "ID_PERIODO_NOMINA")
  USING INDEX  ENABLE
   )
/

