CREATE TABLE "NOVEDADES_MENSUALES" 
   (	"ID_NOVEDAD_MENSUAL" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"TIPO" VARCHAR2(20 CHAR) NOT NULL ENABLE, 
	"MES" DATE NOT NULL ENABLE, 
	"CANTIDAD" NUMBER(12,2) DEFAULT 1 NOT NULL ENABLE, 
	"MONTO" NUMBER(12,2), 
	"VALOR_UNITARIO" NUMBER(20,8), 
	"RECARGO" NUMBER(9,4), 
	"DESCRIPCION" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"REFERENCIA" VARCHAR2(100 CHAR), 
	"AUTORIZACION" VARCHAR2(12 CHAR) DEFAULT 'APROBADA' NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(10 CHAR) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"ID_NOMINA_EMPLEADO" NUMBER, 
	"ID_AUSENCIA" NUMBER, 
	"ID_PARQUEO_SUSCRIPCION" NUMBER, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CLAVE_REFERENCIA" VARCHAR2(200 CHAR), 
	 CONSTRAINT "CK_NOVEDADES_MENSUALES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_NOVEDADES_MENSUALES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION>=FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_NOV_MES_1" CHECK (TIPO IN ('HORAS_EXTRA','COMISION','CONSUMO_TIENDA','AUSENCIA','PARQUEO')) ENABLE, 
	 CONSTRAINT "CK_NOV_MES_2" CHECK (MES=TRUNC(MES,'MM') AND CANTIDAD>0 AND MONTO>=0 AND VALOR_UNITARIO>=0 AND RECARGO>=0) ENABLE, 
	 CONSTRAINT "CK_NOV_MES_3" CHECK (AUTORIZACION IN ('PENDIENTE','APROBADA','RECHAZADA')) ENABLE, 
	 CONSTRAINT "CK_NOV_MES_4" CHECK ((ESTADO='PENDIENTE' AND ID_NOMINA_EMPLEADO IS NULL) OR (ESTADO='APLICADA' AND ID_NOMINA_EMPLEADO IS NOT NULL)) ENABLE, 
	 CONSTRAINT "PK_NOVEDADES_MENSUALES" PRIMARY KEY ("ID_NOVEDAD_MENSUAL")
  USING INDEX  ENABLE
   )
/

