-- TRIGGER: TR_SOLICITUDES_CODIGO
CREATE OR REPLACE EDITIONABLE TRIGGER "TR_SOLICITUDES_CODIGO" 
BEFORE INSERT OR UPDATE OF CODIGO,CODIGO_ANTERIOR ON SOLICITUDES FOR EACH ROW
BEGIN
  IF INSERTING THEN
    :NEW.CODIGO_ANTERIOR:=:NEW.CODIGO;
    :NEW.CODIGO:=N2_CODIGOS.ASIGNAR('solicitudes',NULL,NULL,:NEW.FECHA_CREACION,:NEW.CODIGO);
  ELSIF :NEW.CODIGO<>:OLD.CODIGO OR :NEW.CODIGO IS NULL OR NVL(:NEW.CODIGO_ANTERIOR,CHR(0))<>NVL(:OLD.CODIGO_ANTERIOR,CHR(0)) THEN
    RAISE_APPLICATION_ERROR(-20042,'El código asignado y su referencia anterior son inmutables.');
  END IF;
END;
/
